#include "mspa/persistence/serialization.hpp"
#include <cstring>
#include <limits>
#include <string>
namespace mspa {namespace{
struct W{std::vector<std::uint8_t>b;std::size_t max;bool ok=true;void raw(const void*p,std::size_t n){if(!ok||b.size()>max||n>max-b.size()){ok=false;return;}const auto*x=static_cast<const std::uint8_t*>(p);b.insert(b.end(),x,x+n);}void u8(std::uint8_t x){raw(&x,1);}void u32(std::uint32_t x){for(int i=0;i<4;++i)u8(static_cast<std::uint8_t>(x>>(8*i)));}void u64(std::uint64_t x){for(int i=0;i<8;++i)u8(static_cast<std::uint8_t>(x>>(8*i)));}void f(float x){std::uint32_t u;static_assert(sizeof(u)==sizeof(x),"");std::memcpy(&u,&x,4);u32(u);}void str(const std::string&s){if(s.size()>std::numeric_limits<std::uint32_t>::max()){ok=false;return;}u32(static_cast<std::uint32_t>(s.size()));raw(s.data(),s.size());}};
struct R{const std::vector<std::uint8_t>&b;std::size_t p=0;bool ok=true;bool take(std::size_t n){if(!ok||n>b.size()-std::min(p,b.size())){ok=false;return false;}return true;}std::uint8_t u8(){if(!take(1))return 0;return b[p++];}std::uint32_t u32(){std::uint32_t x=0;for(int i=0;i<4;++i)x|=static_cast<std::uint32_t>(u8())<<(8*i);return x;}std::uint64_t u64(){std::uint64_t x=0;for(int i=0;i<8;++i)x|=static_cast<std::uint64_t>(u8())<<(8*i);return x;}float f(){auto u=u32();float x;std::memcpy(&x,&u,4);return x;}std::string str(std::size_t max=65536){auto n=u32();if(n>max||!take(n)){ok=false;return{};}std::string s(reinterpret_cast<const char*>(b.data()+p),n);p+=n;return s;}};
void agent(W&w,AgentId a){w.u64(a.world.value());w.u64(a.local_id);}AgentId agent(R&r){return {WorldId(r.u64()),r.u64()};}void prop(W&w,const Proposition&p){w.u64(p.predicate.value());w.u64(p.name_space.value());w.u8(p.positive);w.u32(static_cast<std::uint32_t>(p.arguments.size()));for(const auto&a:p.arguments){w.str(a.role);w.str(a.value);w.u8(a.has_agent);if(a.has_agent)agent(w,a.agent);w.u8(a.has_concept);if(a.has_concept)w.u64(a.concept_id.value());}w.u32(static_cast<std::uint32_t>(p.qualifiers.size()));for(const auto&q:p.qualifiers){w.str(q.first);w.str(q.second);}w.u8(p.has_time);if(p.has_time)w.u64(p.time.ticks());w.str(p.provenance);}Proposition prop(R&r){Proposition p{};p.predicate=PredicateId(r.u64());p.name_space=NamespaceId(r.u64());p.positive=r.u8()!=0;auto n=r.u32();if(n>256){r.ok=false;return p;}for(std::uint32_t i=0;i<n;++i){PropositionArg a{};a.role=r.str();a.value=r.str();a.has_agent=r.u8()!=0;if(a.has_agent)a.agent=agent(r);a.has_concept=r.u8()!=0;if(a.has_concept)a.concept_id=ConceptId(r.u64());p.arguments.push_back(std::move(a));}auto q=r.u32();if(q>256){r.ok=false;return p;}for(std::uint32_t i=0;i<q;++i)p.qualifiers.emplace(r.str(),r.str());p.has_time=r.u8()!=0;if(p.has_time)p.time=PsychTime(r.u64());p.provenance=r.str();return p;}
}
Result<std::vector<std::uint8_t>>serialize_agent(const ExportedAgent&e,const SerializationOptions&o){W w{{},o.max_bytes,true};w.raw("MSPA",4);w.u32(serialization_format_version);w.u32(e.state.schema_version);agent(w,e.state.id);w.u64(e.origin_time_domain.id.value());w.u64(e.origin_time_domain.scale.ticks_per_second_num);w.u64(e.origin_time_domain.scale.ticks_per_second_den);w.u64(e.exported_at.ticks());const auto&p=e.state.personality;w.f(p.sociability);w.f(p.stability);w.f(p.empathy);w.f(p.persistence);w.f(p.curiosity);w.f(p.boldness);w.u32(static_cast<std::uint32_t>(e.state.values.size()));for(auto&v:e.state.values){w.u64(v.concept_id.value());w.f(v.intensity);}w.u32(static_cast<std::uint32_t>(e.state.beliefs.size()));for(auto&b:e.state.beliefs){w.u64(b.id.value());prop(w,b.proposition);w.f(b.certainty);w.f(b.emotional_load);w.u8(static_cast<std::uint8_t>(b.source));agent(w,b.source_agent);w.u32(b.evidence_count);w.u64(b.updated_at.ticks());}w.u32(static_cast<std::uint32_t>(e.state.emotions.size()));for(auto&x:e.state.emotions){w.u8(static_cast<std::uint8_t>(x.kind));w.f(x.intensity);w.u64(x.started_at.ticks());w.u64(x.updated_at.ticks());}w.f(e.state.mood.valence);w.f(e.state.mood.activation);w.u64(e.state.mood.updated_at.ticks());w.u32(static_cast<std::uint32_t>(e.state.goals.size()));for(auto&g:e.state.goals){w.u64(g.id.value());w.u64(g.concept_id.value());w.f(g.priority);w.f(g.commitment);w.u8(static_cast<std::uint8_t>(g.status));w.u64(g.created_at.ticks());w.u64(g.updated_at.ticks());}w.u32(static_cast<std::uint32_t>(e.state.memories.size()));for(auto&m:e.state.memories){w.u64(m.id.value());prop(w,m.proposition);w.f(m.importance);w.f(m.emotional_load);w.f(m.certainty);w.u8(static_cast<std::uint8_t>(m.source));w.u32(static_cast<std::uint32_t>(m.participants.size()));for(auto&a:m.participants)agent(w,a);w.u32(m.reactivations);w.u64(m.event_time.ticks());w.u64(m.last_reactivated_at.ticks());}w.u32(static_cast<std::uint32_t>(e.state.relationships.size()));for(auto&r:e.state.relationships){agent(w,r.other);w.f(r.affection);w.f(r.trust);w.f(r.respect);w.f(r.familiarity);}w.u32(static_cast<std::uint32_t>(e.state.learned_expectations.size()));for(auto&x:e.state.learned_expectations){w.u64(x.action.value());w.u32(static_cast<std::uint32_t>(x.context_tags.size()));for(auto&t:x.context_tags)w.str(t);w.str(x.outcome_tag);w.u32(x.attempts);w.u32(x.successes);w.f(x.confidence);w.u64(x.last_activation.ticks());}w.u64(e.state.current_intent.value());w.u64(e.state.rng_state.state);w.u64(e.state.last_processed_time.ticks());if(!w.ok)return make_error(ErrorCode::QuotaExceeded,"serialized agent exceeds byte limit");return std::move(w.b);}
Result<ExportedAgent>deserialize_agent(const std::vector<std::uint8_t>&bytes,const SerializationOptions&o){if(bytes.size()>o.max_bytes)return make_error(ErrorCode::QuotaExceeded,"serialized agent exceeds byte limit");if(bytes.size()<12||std::memcmp(bytes.data(),"MSPA",4)!=0)return make_error(ErrorCode::SerializationError,"invalid MSPA serialization magic");R r{bytes,4,true};auto fmt=r.u32();if(fmt!=serialization_format_version)return make_error(ErrorCode::VersionMismatch,"unsupported serialization format");ExportedAgent e{};e.state.schema_version=r.u32();e.state.id=agent(r);e.origin_time_domain.id=TimeDomainId(r.u64());e.origin_time_domain.scale={r.u64(),r.u64()};e.exported_at=PsychTime(r.u64());auto&p=e.state.personality;p.sociability=r.f();p.stability=r.f();p.empathy=r.f();p.persistence=r.f();p.curiosity=r.f();p.boldness=r.f();auto count=[&](std::uint32_t hard){auto n=r.u32();if(n>hard)r.ok=false;return n;};for(std::uint32_t i=0,n=count(65536);i<n&&r.ok;++i)e.state.values.push_back({ConceptId(r.u64()),r.f()});for(std::uint32_t i=0,n=count(65536);i<n&&r.ok;++i){BeliefState b{};b.id=BeliefId(r.u64());b.proposition=prop(r);b.certainty=r.f();b.emotional_load=r.f();b.source=static_cast<BeliefSource>(r.u8());b.source_agent=agent(r);b.evidence_count=r.u32();b.updated_at=PsychTime(r.u64());e.state.beliefs.push_back(std::move(b));}for(std::uint32_t i=0,n=count(256);i<n&&r.ok;++i)e.state.emotions.push_back({static_cast<BasicEmotion>(r.u8()),r.f(),PsychTime(r.u64()),PsychTime(r.u64())});e.state.mood.valence=r.f();e.state.mood.activation=r.f();e.state.mood.updated_at=PsychTime(r.u64());for(std::uint32_t i=0,n=count(4096);i<n&&r.ok;++i){GoalState g{};g.id=GoalId(r.u64());g.concept_id=ConceptId(r.u64());g.priority=r.f();g.commitment=r.f();g.status=static_cast<GoalStatus>(r.u8());g.created_at=PsychTime(r.u64());g.updated_at=PsychTime(r.u64());e.state.goals.push_back(g);}for(std::uint32_t i=0,n=count(65536);i<n&&r.ok;++i){MemoryState m{};m.id=MemoryId(r.u64());m.proposition=prop(r);m.importance=r.f();m.emotional_load=r.f();m.certainty=r.f();m.source=static_cast<BeliefSource>(r.u8());auto pc=count(65536);for(std::uint32_t j=0;j<pc&&r.ok;++j)m.participants.push_back(agent(r));m.reactivations=r.u32();m.event_time=PsychTime(r.u64());m.last_reactivated_at=PsychTime(r.u64());e.state.memories.push_back(std::move(m));}for(std::uint32_t i=0,n=count(65536);i<n&&r.ok;++i){RelationshipState x{};x.other=agent(r);x.affection=r.f();x.trust=r.f();x.respect=r.f();x.familiarity=r.f();e.state.relationships.push_back(x);}for(std::uint32_t i=0,n=count(65536);i<n&&r.ok;++i){LearnedExpectation x{};x.action=ActionTypeId(r.u64());auto tc=count(1024);for(std::uint32_t j=0;j<tc&&r.ok;++j)x.context_tags.push_back(r.str());x.outcome_tag=r.str();x.attempts=r.u32();x.successes=r.u32();x.confidence=r.f();x.last_activation=PsychTime(r.u64());e.state.learned_expectations.push_back(std::move(x));}e.state.current_intent=ActionContinuityKey(r.u64());e.state.rng_state.state=r.u64();e.state.last_processed_time=PsychTime(r.u64());if(!r.ok||r.p!=bytes.size())return make_error(ErrorCode::SerializationError,"truncated or malformed serialized agent");auto m=migrate_agent_state(e.state);if(!m)return *m.error_if();return e;}
}
